def runs(row):
    out=[];j=0;w=len(row)
    while j<w:
        if row[j]:
            k=j
            while k<w and row[k]: k+=1
            if k-j>=2: out.append((j,row[j:k]))
            j=k
        else: j+=1
    return out

def transform(g):
    h,w=len(g),len(g[0])
    segs={}
    for row in g:
        for s,r in runs(row):
            for i,v in enumerate(r):
                segs.setdefault(v,(s-i,r))
    out=[[0]*w for _ in range(h)]
    for i,row in enumerate(g):
        for s,r in runs(row):
            out[i][s:s+len(r)]=r
        for j,v in enumerate(row):
            if v and not any(s<=j<s+len(r) for s,r in runs(row)):
                s,ks=segs[v]
                for d in range(len(ks)):
                    c=s+d
                    if 0<=c<w: out[i][c]=ks[d]
    return out

